import { Directive, HostListener, ElementRef, Renderer2, Input, OnInit } from '@angular/core';

export enum DfDirection {
  'append',
  'prepend'
}

/**
 * My dfInputIcon directive
 */
@Directive({
  exportAs: 'dfInputIcon',
  selector: '[dfInputIcon]'
})
export class DfInputIconDirective implements OnInit {

  @Input() dfInputIcon: DfDirection[] = [];

  isFocused = false;
  constructor(private renderer: Renderer2, private el: ElementRef) {}

  ngOnInit() {
    this.renderer.addClass(this.el.nativeElement, 'df-input-withicon');
    this.dfInputIcon.forEach(direction => {
      this.renderer.addClass(this.el.nativeElement, direction.toString());
    });
  }

  /**
   * onBlur catch blur event to set the focused to false
   * @param e
   */
  @HostListener('blur', ['$event'])
  onBlur(e) {
    this.isFocused = false;
  }

  @HostListener('focus', ['$event'])
  onFocus(e) {
    this.isFocused = true;
  }

}
