import { NgbModalOptions, NgbModalRef } from '@ng-bootstrap/ng-bootstrap/modal/modal.module';
import { NgbModal } from '@ng-bootstrap/ng-bootstrap';
import { Injectable, Renderer2, RendererFactory2, ModuleWithProviders, NgModule } from '@angular/core';

@Injectable()
export class DfModalService {

  private renderer: Renderer2;

  constructor(private modalService: NgbModal, private rendererFactory: RendererFactory2) {
    this.renderer = rendererFactory.createRenderer(null, null);
   }

  open(content: any, options?: NgbModalOptions): NgbModalRef {
    let modalRef: NgbModalRef;
      if (options && options.container) {
        modalRef = this.modalService.open(content, options);
      } else {
        modalRef = this.modalService.open(content, Object.assign({},
            { container: '.design-factory-v2' }, options));
      }
      // we add the 'df-moda-open' class to the body when the modal is open. We remove it when the modal is closed/dismissed
      this.renderer.addClass(document.body, 'df-modal-open');
      modalRef.result.then(() => {
        this.renderer.removeClass(document.body, 'df-modal-open');
      }, () => {
        this.renderer.removeClass(document.body, 'df-modal-open');
      });
    return modalRef;
  }
}

@NgModule({
  declarations: [],
  entryComponents: [],
  providers: [DfModalService]
})
export class DfModalModule {
  static forRoot(): ModuleWithProviders { return {ngModule: DfModalModule, providers: [DfModalService]}; }
}
